export interface BiquoteTick {
    symbol: string;
    description?: string | null;
    bid: number;
    ask: number;
    /** Midpoint of bid/ask — use this as the price. `last`/`volume` are always 0 on this feed. */
    mid: number;
    spread: number;
    last: number;
    volume: number;
    high: number;
    low: number;
    direction: "UP" | "DOWN" | "FLAT" | string;
    dayDiffPercent: number;
    timestamp: string;
    /** MetaTrader's native format. NOT reliably parseable by `new Date()` — parse `timestamp`. */
    time?: string;
    source: string;
    /** "open" while the symbol is quoting, "closed" once it has stopped. Always present. */
    marketState: "open" | "closed";
    /** True once the quote is over 5 minutes old. Always present. */
    stale: boolean;
    /** Seconds since the quote was taken. 0 while live. Always present. */
    quoteAgeSeconds: number;
    /** When the quote was taken. Always present. */
    lastQuoteAt: string;
}

export interface BiquoteBar {
    openTime: string;
    open: number;
    high: number;
    low: number;
    close: number;
    volume: number;
    tickVolume: number;
    isOpen: boolean;
}

export interface BiquoteSymbol {
    name: string;
    description: string;
    type: string;
    exchange: string;
    source: string;
    digits?: number;
    tickSize?: number;
    tickValue?: number;
    contractSize?: number;
    currency?: string;
    /** The broker lists this instrument. True for nearly everything. */
    isActive?: boolean;
    /** Ticks are flowing right now. False for FX and equities outside market hours. */
    hasData?: boolean;
}

export interface BiquoteNewsItem {
    title: string;
    description: string;
    url: string;
    publisher: string | null;
    publishedDate: string;
    imageUrl: string | null;
}

export type NewsKind = "market" | "crypto" | "technology" | "hn" | "search";

export interface BiquoteCalendarEvent {
    id: string;
    eventId: string;
    time: string;
    period?: string | null;
    countryCode: string;
    currency: string;
    name: string;
    importance: "none" | "low" | "medium" | "high";
    type: "event" | "indicator" | "holiday";
    unit?: string | null;
    multiplier?: string | null;
    actual?: number | null;
    forecast?: number | null;
    previous?: number | null;
    revisedPrevious?: number | null;
    timeMode: "exact" | "date" | "notime" | "tentative";
}

export interface OhlcOptions {
    interval?: "1m" | "5m" | "15m" | "30m" | "1h" | "4h" | "1d";
    limit?: number;
    from?: string;
    to?: string;
}

export declare class Biquote {
    constructor(opts?: { baseUrl?: string; apiKey?: string });
    tick(symbol: string, opts?: { allowStale?: boolean }): Promise<BiquoteTick>;
    latest(symbols: string[], opts?: { allowStale?: boolean }): Promise<Record<string, BiquoteTick>>;
    ohlc(symbol: string, opts?: OhlcOptions): Promise<BiquoteBar[]>;
    symbols(opts?: { liveOnly?: boolean; quotedWithinDays?: number; activeOnly?: boolean; type?: string; exchange?: string; source?: string }): Promise<BiquoteSymbol[]>;
    symbol(name: string): Promise<BiquoteSymbol>;
    search(q: string, opts?: { liveOnly?: boolean; limit?: number }): Promise<BiquoteSymbol[]>;
    active(): Promise<BiquoteSymbol[]>;
    gainers(opts?: { type?: string; exchange?: string; limit?: number; period?: string }): Promise<unknown>;
    losers(opts?: { type?: string; exchange?: string; limit?: number; period?: string }): Promise<unknown>;
    mostActive(opts?: { type?: string; exchange?: string; limit?: number }): Promise<unknown>;
    marketSummary(opts?: { type?: string; exchange?: string }): Promise<unknown>;
    calendar(opts?: { from?: string; to?: string; countries?: string; importance?: string; type?: string; limit?: number }): Promise<BiquoteCalendarEvent[]>;
    calendarUpcoming(opts?: { limit?: number; countries?: string; importance?: string }): Promise<BiquoteCalendarEvent[]>;
    calendarCountries(): Promise<unknown>;
    news(kind?: NewsKind, opts?: { q?: string; language?: string; country?: string; maxResults?: number }): Promise<BiquoteNewsItem[]>;
}

export default Biquote;
